-- ---------- insert_data.sql ----------
-- GENERATED by scripts/build_dist.sh. Do not edit by hand.
-- Run AFTER create_database_and_schema.sql. Seeds all 17 tables in
-- dependency order. Hardcoded FK values assume freshly created tables.

USE AppointmentBookingDB;
GO

-- Guard: refuse to run against tables that already hold data, since
-- the hardcoded FK values would point at the wrong rows. SET NOEXEC ON
-- skips every remaining batch; it's switched back off at the end.
IF EXISTS (SELECT 1 FROM dbo.Business)
BEGIN
    RAISERROR('Tables already contain data. Run create_database_and_schema.sql first, then rerun this script.', 16, 1);
    SET NOEXEC ON;
END
GO

